#!/usr/bin/env python3
"""
Cross-Origin Resource Sharing (CORS) implementation for a single API.

Provides:
- CORSPolicy: configuration container
- is_origin_allowed: origin matching (exact, "*", and "*.example.com" wildcards)
- evaluate_cors: framework-agnostic decision function
- cors_middleware: WSGI middleware applying the policy
- create_app: sample JSON API protected by CORS
- main: runs the sample API with wsgiref
"""

import json
import sys
from dataclasses import dataclass, field
from wsgiref.simple_server import make_server


DEFAULT_METHODS = ["GET", "HEAD", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"]
DEFAULT_HEADERS = ["Content-Type", "Authorization"]


@dataclass
class CORSPolicy:
    allowed_origins: list = field(default_factory=lambda: ["*"])
    allowed_methods: list = field(default_factory=lambda: list(DEFAULT_METHODS))
    allowed_headers: list = field(default_factory=lambda: list(DEFAULT_HEADERS))
    exposed_headers: list = field(default_factory=list)
    allow_credentials: bool = False
    max_age: int = 600


def normalize_origin(origin):
    if origin is None:
        return None
    return origin.strip().rstrip("/").lower()


def get_header(headers, name):
    """Case-insensitive header lookup over a dict or list of (name, value) pairs."""
    target = name.lower()
    if isinstance(headers, dict):
        items = headers.items()
    else:
        items = headers
    for key, value in items:
        if key.lower() == target:
            return value
    return None


def is_origin_allowed(origin, policy):
    origin = normalize_origin(origin)
    if not origin:
        return False
    for allowed in policy.allowed_origins:
        entry = normalize_origin(allowed)
        if entry == "*":
            return True
        if entry == origin:
            return True
        if entry.startswith("*."):
            suffix = entry[1:]  # ".example.com"
            scheme_end = origin.find("://")
            host = origin[scheme_end + 3:] if scheme_end != -1 else origin
            host = host.split("/")[0].split(":")[0]
            if host.endswith(suffix):
                return True
    return False


def _split_csv(value):
    if not value:
        return []
    return [part.strip() for part in value.split(",") if part.strip()]


def _vary(existing, addition):
    if not existing:
        return addition
    names = [n.strip().lower() for n in existing.split(",")]
    if addition.lower() in names:
        return existing
    return existing + ", " + addition


def evaluate_cors(method, headers, policy):
    """
    Decide how to handle a request under the CORS policy.

    Returns a dict:
      {
        "kind": "not_cors" | "preflight" | "actual" | "rejected",
        "status": int or None (status for preflight responses),
        "headers": dict of CORS response headers to add,
        "allowed": bool
      }
    """
    method = (method or "GET").upper()
    origin = get_header(headers, "Origin")

    if origin is None:
        return {"kind": "not_cors", "status": None, "headers": {}, "allowed": True}

    base_headers = {"Vary": "Origin"}

    if not is_origin_allowed(origin, policy):
        return {"kind": "rejected", "status": None, "headers": base_headers, "allowed": False}

    is_preflight = (
        method == "OPTIONS"
        and get_header(headers, "Access-Control-Request-Method") is not None
    )

    # Origin value echoed when credentials are allowed or policy is not wildcard
    if "*" in [normalize_origin(o) for o in policy.allowed_origins] and not policy.allow_credentials:
        allow_origin = "*"
    else:
        allow_origin = origin

    response_headers = dict(base_headers)
    response_headers["Access-Control-Allow-Origin"] = allow_origin
    if policy.allow_credentials:
        response_headers["Access-Control-Allow-Credentials"] = "true"

    if not is_preflight:
        if policy.exposed_headers:
            response_headers["Access-Control-Expose-Headers"] = ", ".join(policy.exposed_headers)
        return {"kind": "actual", "status": None, "headers": response_headers, "allowed": True}

    # Preflight checks
    requested_method = get_header(headers, "Access-Control-Request-Method").strip().upper()
    allowed_methods = [m.upper() for m in policy.allowed_methods]
    if requested_method not in allowed_methods:
        return {"kind": "rejected", "status": None, "headers": base_headers, "allowed": False}

    requested_headers = _split_csv(get_header(headers, "Access-Control-Request-Headers"))
    allowed_header_names = {h.lower() for h in policy.allowed_headers}
    if any(h.lower() not in allowed_header_names for h in requested_headers):
        return {"kind": "rejected", "status": None, "headers": base_headers, "allowed": False}

    response_headers["Access-Control-Allow-Methods"] = ", ".join(policy.allowed_methods)
    if policy.allowed_headers:
        response_headers["Access-Control-Allow-Headers"] = ", ".join(policy.allowed_headers)
    response_headers["Access-Control-Max-Age"] = str(policy.max_age)
    response_headers["Vary"] = _vary(
        _vary("Origin", "Access-Control-Request-Method"),
        "Access-Control-Request-Headers",
    )

    return {"kind": "preflight", "status": 204, "headers": response_headers, "allowed": True}


def cors_middleware(app, policy):
    """WSGI middleware enforcing the CORS policy around a WSGI application."""

    def middleware(environ, start_response):
        headers = []
        for key, value in environ.items():
            if key.startswith("HTTP_"):
                name = key[5:].replace("_", "-").title()
                headers.append((name, value))
        if environ.get("CONTENT_TYPE"):
            headers.append(("Content-Type", environ["CONTENT_TYPE"]))

        decision = evaluate_cors(environ.get("REQUEST_METHOD", "GET"), headers, policy)

        if decision["kind"] == "preflight":
            start_response(
                "204 No Content",
                [(k, v) for k, v in decision["headers"].items()] + [("Content-Length", "0")],
            )
            return [b""]

        def cors_start_response(status, response_headers, exc_info=None):
            if decision["allowed"] and decision["headers"]:
                existing = {k.lower(): k for k, _ in response_headers}
                merged = list(response_headers)
                for k, v in decision["headers"].items():
                    if k.lower() in existing:
                        merged = [(hk, hv) for hk, hv in merged if hk.lower() != k.lower()]
                    merged.append((k, v))
                response_headers = merged
            if exc_info is not None:
                return start_response(status, response_headers, exc_info)
            return start_response(status, response_headers)

        return app(environ, cors_start_response)

    return middleware


def create_app():
    """Sample JSON API used for demonstration."""
    items = {"1": {"id": "1", "name": "alpha"}, "2": {"id": "2", "name": "beta"}}

    def app(environ, start_response):
        method = environ.get("REQUEST_METHOD", "GET")
        path = environ.get("PATH_INFO", "/")

        def respond(status, payload):
            body = json.dumps(payload).encode("utf-8")
            start_response(
                status,
                [("Content-Type", "application/json"), ("Content-Length", str(len(body)))],
            )
            return [body]

        if path == "/api/items" and method == "GET":
            return respond("200 OK", list(items.values()))
        if path.startswith("/api/items/") and method == "GET":
            item_id = path.rsplit("/", 1)[-1]
            if item_id in items:
                return respond("200 OK", items[item_id])
            return respond("404 Not Found", {"error": "not found"})
        return respond("404 Not Found", {"error": "no route"})

    return app


